## 🔹 STEP 4: `js/app.js` (The Dynamic Engine)

This file reads `config.js`, injects HTML, handles clicks, manages cart, and adds animations.

```javascript
// js/app.js
document.addEventListener('DOMContentLoaded', () => {
  // 1. Render Navbar Links
  const navContainer = document.getElementById('navLinksContainer');
  CONFIG.navLinks.forEach(link => {
    const li = document.createElement('li');
    li.className = 'nav-item';
    li.innerHTML = `<a class="nav-link fw-medium" href="${link.href}">${link.label}</a>`;
    navContainer.appendChild(li);
  });

  // 2. Render Hero
  document.getElementById('heroBadge').textContent = "Premium Footwear";
  document.getElementById('heroTitle').innerHTML = `Step Into <em>Quality.</em><br/>Walk With <em>Confidence.</em>`;
  document.getElementById('heroSubtext').textContent = CONFIG.brand.subtext;
  document.querySelector('#home .navbar-brand')?.textContent || (document.getElementById('navBrand').textContent = CONFIG.brand.name);

  // 3. Render Categories
  const catContainer = document.getElementById('categoriesContainer');
  CONFIG.categories.forEach(cat => {
    catContainer.innerHTML += `
      <div class="col-md-6 col-lg-4 col-xl-3 reveal">
        <a href="#${cat.id}" class="cat-card card-hover">
          <img src="${cat.image}" alt="${cat.name}" loading="lazy">
          <div class="overlay-text">
            <h3 class="mb-1 fs-5">${cat.name}</h3>
            <span>Explore <i class="fas fa-arrow-right"></i></span>
          </div>
        </a>
      </div>`;
  });

  // 4. Helper: Render Collection Grids
  function renderCollection(id, containerId, items) {
    const container = document.getElementById(containerId);
    items.forEach(item => {
      container.innerHTML += `
        <div class="col-md-6 col-lg-4 col-xl-2 reveal">
          <div class="collection-card card-hover">
            <div class="card-img-wrap"><img src="${item.img}" alt="${item.name}" loading="lazy"></div>
            <div class="card-body-custom text-center">
              <h4 class="fs-6 mb-1">${item.name}</h4>
              <small class="text-muted">${item.desc}</small>
            </div>
          </div>
        </div>`;
    });
  }
  renderCollection('men', 'menContainer', CONFIG.collections.men);
  renderCollection('women', 'womenContainer', CONFIG.collections.women);
  renderCollection('kids', 'kidsContainer', CONFIG.collections.kids);
  renderCollection('accessories', 'accessoriesContainer', CONFIG.collections.accessories);

  // 5. Render Products
  const prodContainer = document.getElementById('productsContainer');
  CONFIG.products.forEach(p => {
    const badgeHTML = p.badge ? `<span class="badge-custom badge-${p.badge.toLowerCase()}">${p.badge}</span>` : '';
    const oldPriceHTML = p.oldPrice ? `<span class="price-old">${CONFIG.currency}${p.oldPrice.toLocaleString()}</span>` : '';
    prodContainer.innerHTML += `
      <div class="col-md-6 col-lg-4 col-xl-3 reveal">
        <div class="product-card card-hover">
          ${badgeHTML}
          <div class="card-img-wrap"><img src="${p.img}" alt="${p.name}" loading="lazy"></div>
          <div class="card-body-custom">
            <h4 class="fs-6 mb-2 fw-semibold">${p.name}</h4>
            <p class="text-muted small mb-2">${p.desc}</p>
            <div class="mb-3">
              <span class="price-current">${CONFIG.currency}${p.price.toLocaleString()}</span>
              ${oldPriceHTML}
            </div>
            <div class="d-grid gap-2">
              <button class="btn btn-outline-dark btn-sm btn-cart" data-id="${p.id}" data-name="${p.name}">Add to Cart</button>
              <button class="btn btn-dark btn-sm btn-buy" data-wa="${CONFIG.contact.whatsapp}" data-name="${p.name}" data-price="${p.price}">Buy Now</button>
            </div>
          </div>
        </div>
      </div>`;
  });

  // 6. Render Features
  const featContainer = document.getElementById('featuresContainer');
  CONFIG.features.forEach(f => {
    featContainer.innerHTML += `
      <div class="col-md-6 col-lg-4 reveal">
        <div class="feature-card">
          <div class="feature-icon"><i class="fas ${f.icon}"></i></div>
          <h3 class="fs-5 mb-2 text-white">${f.title}</h3>
          <p class="text-light opacity-75 small">${f.desc}</p>
        </div>
      </div>`;
  });

  // 7. Render Testimonials
  const testContainer = document.getElementById('testimonialsContainer');
  CONFIG.testimonials.forEach(t => {
    const stars = Array(t.rating).fill('<i class="fas fa-star text-warning"></i>').join('');
    testContainer.innerHTML += `
      <div class="col-md-4 reveal">
        <div class="testimonial-card">
          <div class="mb-2">${stars}</div>
          <p class="fst-italic small mb-3">"${t.text}"</p>
          <div class="d-flex align-items-center gap-2">
            <div class="author-avatar">${t.initials}</div>
            <div>
              <h6 class="mb-0 fs-6">${t.name}</h6>
              <small class="text-muted">${t.location}</small>
            </div>
          </div>
        </div>
      </div>`;
  });

  // 8. Render Footer & CTA Links
  document.getElementById('footerBrand').innerHTML = `${CONFIG.brand.name} <span style="color:var(--gold)">.</span>`;
  document.getElementById('footerAddress').textContent = CONFIG.contact.address;
  document.getElementById('footerPhone').textContent = CONFIG.contact.phone;
  document.getElementById('footerEmail').textContent = CONFIG.contact.email;
  document.getElementById('footerHours').textContent = CONFIG.contact.hours;
  document.getElementById('emailBtn').href = `mailto:${CONFIG.contact.email}`;
  document.getElementById('whatsappBtn').href = `https://wa.me/${CONFIG.contact.whatsapp.replace(/\D/g,'')}?text=Hello%20BUDE%20.T%20FootWears,%20I'd%20like%20to%20inquire%20about%20a%20product.`;

  const socialContainer = document.getElementById('socialsContainer');
  const socialMap = { facebook:'fa-facebook-f', instagram:'fa-instagram', twitter:'fa-twitter', tiktok:'fa-tiktok', whatsapp:'fa-whatsapp' };
  Object.entries(CONFIG.socials).forEach(([key, url]) => {
    if(socialMap[key]) {
      socialContainer.innerHTML += `<a href="${url}" target="_blank" class="me-2"><i class="fab ${socialMap[key]}"></i></a>`;
    }
  });

  // 9. Cart Logic (LocalStorage + Toast)
  let cartCount = parseInt(localStorage.getItem('bude_cart_count')) || 0;
  const cartBadge = document.getElementById('cartCount');
  cartBadge.textContent = cartCount;

  document.getElementById('productsContainer').addEventListener('click', (e) => {
    const cartBtn = e.target.closest('.btn-cart');
    const buyBtn = e.target.closest('.btn-buy');

    if (cartBtn) {
      cartCount++;
      localStorage.setItem('bude_cart_count', cartCount);
      cartBadge.textContent = cartCount;
      bootstrap.Toast.getOrCreateInstance(document.getElementById('cartToast')).show();

      const originalText = cartBtn.textContent;
      cartBtn.textContent = 'Added ✓';
      cartBtn.classList.replace('btn-outline-dark', 'btn-success');
      setTimeout(() => {
        cartBtn.textContent = originalText;
        cartBtn.classList.replace('btn-success', 'btn-outline-dark');
      }, 1200);
    }

    if (buyBtn) {
      const name = buyBtn.dataset.name;
      const price = buyBtn.dataset.price;
      const wa = buyBtn.dataset.wa;
      const msg = encodeURIComponent(`Hello BUDE .T FootWears, I'd like to buy: ${name} at ${CONFIG.currency}${price}. Please confirm availability.`);
      window.open(`https://wa.me/${wa.replace(/\D/g,'')}?text=${msg}`, '_blank');
    }
  });

  // 10. Scroll Reveal
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1 });
  document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

  // 11. Smooth Scroll for Nav Links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      const targetId = this.getAttribute('href');
      if(targetId === '#') return;
      const target = document.querySelector(targetId);
      if(target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        // Close mobile nav if open
        const navCollapse = document.getElementById('navbarNav');
        if(navCollapse.classList.contains('show')) {
          new bootstrap.Collapse(navCollapse, { toggle: true });
        }
      }
    });
  });

  // 12. Navbar background on scroll
  window.addEventListener('scroll', () => {
    const nav = document.getElementById('mainNav');
    if(window.scrollY > 50) {
      nav.classList.add('shadow-sm');
    } else {
      nav.classList.remove('shadow-sm');
    }
  });
});
```

📝 **What this does:** 
- Reads `config.js` and injects everything
- Makes "Add to Cart" update a badge + show a toast
- Makes "Buy Now" open WhatsApp with pre-filled product name & price
- Smooth scrolls all `#` links
- Closes mobile menu on click
- Persists cart count across refreshes using `localStorage`

