/* css/style.css */
/* ---------- RESET & BASE ---------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: 'Inter', sans-serif;
  color: #1a1a1a;
  background: #fff;
  line-height: 1.6;
  overflow-x: hidden;
}
img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

:root {
  --black: #0a0a0a;
  --white: #ffffff;
  --off-white: #faf8f5;
  --brown: #6b4423;
  --brown-light: #8b5a2b;
  --gold: #c9a961;
  --gold-dark: #a8893f;
  --gray: #6b6b6b;
  --light-gray: #e8e4df;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-md: 0 6px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --radius: 14px;
  --transition: 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

h1, h2, h3, h4 { font-family: 'Playfair Display', serif; font-weight: 700; line-height: 1.2; color: var(--black); }

.container { width: 100%; max-width: 1240px; margin: 0 auto; padding: 0 20px; }

.section { padding: 80px 0; }
.section-title {
  text-align: center;
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  margin-bottom: 12px;
}
.section-subtitle {
  text-align: center;
  color: var(--gray);
  font-size: 1rem;
  max-width: 600px;
  margin: 0 auto 50px;
}
.gold-line {
  width: 60px; height: 3px;
  background: var(--gold);
  margin: 16px auto 20px;
  border-radius: 2px;
}

/* ---------- BUTTONS ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px;
  padding: 14px 30px;
  font-weight: 600;
  font-size: 0.95rem;
  letter-spacing: 0.3px;
  border-radius: 50px;
  transition: var(--transition);
  white-space: nowrap;
}
.btn-primary { background: var(--gold); color: var(--black); }
.btn-primary:hover { background: var(--gold-dark); transform: translateY(-2px); box-shadow: var(--shadow-md); }
.btn-outline { border: 2px solid var(--white); color: var(--white); background: transparent; }
.btn-outline:hover { background: var(--white); color: var(--black); }
.btn-dark { background: var(--black); color: var(--white); }
.btn-dark:hover { background: var(--brown); transform: translateY(-2px); }

/* ---------- HEADER ---------- */
.header {
  position: fixed; top: 0; left: 0; right: 0;
  background: rgba(255,255,255,0.97);
  backdrop-filter: blur(10px);
  z-index: 1000;
  transition: var(--transition);
  border-bottom: 1px solid transparent;
}
.header.scrolled { box-shadow: var(--shadow-sm); border-bottom-color: var(--light-gray); }
.nav {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 0;
  gap: 20px;
  position: relative;
  z-index: 1000;
}
.logo {
  font-family: 'Playfair Display', serif;
  font-size: 1.5rem; font-weight: 800;
  color: var(--black);
  letter-spacing: 0.5px;
}
.logo span { color: var(--gold); }
.nav-links { display: flex; gap: 32px; list-style: none; }
.nav-links a {
  font-size: 0.92rem; font-weight: 500;
