}
.hero-buttons { display: flex; flex-wrap: wrap; gap: 14px; }

/* ---------- CATEGORIES ---------- */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}
.category-card {
  position: relative;
  border-radius: var(--radius);
