}
.category-card:hover span { gap: 12px; }

/* ---------- COLLECTIONS ---------- */
.collection { background: var(--off-white); }
.collection:nth-of-type(even) { background: var(--white); }
.collection-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
