}
.product-card:hover .product-img img { transform: scale(1.05); }
.product-body { padding: 20px; }
.product-body h4 {
  font-family: 'Inter', sans-serif;
  font-size: 1rem; font-weight: 600;
  margin-bottom: 6px;
}
.product-desc { font-size: 0.85rem; color: var(--gray); margin-bottom: 12px; }
.product-price {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 16px;
}
.price-current { font-size: 1.2rem; font-weight: 700; color: var(--brown); }
.price-old { font-size: 0.9rem; color: var(--gray); text-decoration: line-through; }
.product-actions { display: flex; gap: 8px; }
.product-actions button {
  flex: 1;
  padding: 10px;
  font-size: 0.85rem; font-weight: 600;
  border-radius: 8px;
  transition: var(--transition);
}
.btn-cart { background: var(--off-white); color: var(--black); }
.btn-cart:hover { background: var(--light-gray); }
.btn-buy { background: var(--black); color: var(--white); }
.btn-buy:hover { background: var(--brown); }

/* ---------- FEATURES ---------- */
.why-us {
  background: linear-gradient(135deg, var(--black) 0%, #2a1a0f 100%);
