      document.getElementById('menSubtitle').textContent = CONFIG.collections.men.subtitle;
      document.getElementById('womenTitle').textContent = CONFIG.collections.women.title;
      document.getElementById('womenSubtitle').textContent = CONFIG.collections.women.subtitle;
      document.getElementById('kidsTitle').textContent = CONFIG.collections.kids.title;
      document.getElementById('kidsSubtitle').textContent = CONFIG.collections.kids.subtitle;
      document.getElementById('accessoriesTitle').textContent = CONFIG.collections.accessories.title;
      document.getElementById('accessoriesSubtitle').textContent = CONFIG.collections.accessories.subtitle;

      // Set contact links
      document.getElementById('contactEmailLink').href = `mailto:${CONFIG.contact.email}`;
      document.getElementById('whatsappLink').href = `https://wa.me/${CONFIG.contact.whatsapp.replace(/\+/g, '')}`;

      // Sticky header
      const header = document.getElementById('header');
      window.addEventListener('scroll', () => {
        header.classList.toggle('scrolled', window.scrollY > 30);
      });

      // Mobile menu
      const menuToggle = document.getElementById('menuToggle');
      const navLinks = document.getElementById('navLinks');
      menuToggle.addEventListener('click', () => {
        navLinks.classList.toggle('open');
        const icon = menuToggle.querySelector('i');
        icon.classList.toggle('fa-bars');
        icon.classList.toggle('fa-times');
      });

      document.querySelectorAll('.nav-links a').forEach(link => {
        link.addEventListener('click', () => {
          navLinks.classList.remove('open');
          menuToggle.querySelector('i').classList.add('fa-bars');
          menuToggle.querySelector('i').classList.remove('fa-times');
        });
      });

      // Close modals on outside click
      document.querySelectorAll('.modal').forEach(modal => {
        modal.addEventListener('click', (e) => {
          if (e.target === modal) {
            modal.classList.remove('active');
          }
        });
      });
    });
  </script>
